package com.campusvibe.controller;
import com.campusvibe.entity.*; import com.campusvibe.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class CrudController {
 final CategoryRepository categories; final VenueRepository venues; final AnnouncementRepository announcements; final SponsorRepository sponsors; final FeedbackRepository feedback; final NotificationRepository notifications; final ResultRepository results; final ScheduleRepository schedules; final UserRepository users;
 public CrudController(CategoryRepository c,VenueRepository v,AnnouncementRepository a,SponsorRepository s,FeedbackRepository f,NotificationRepository n,ResultRepository r,ScheduleRepository sc,UserRepository u){categories=c;venues=v;announcements=a;sponsors=s;feedback=f;notifications=n;results=r;schedules=sc;users=u;}
 @GetMapping("/categories") public List<Category> cats(){return categories.findAll();} @PostMapping("/categories") @PreAuthorize("hasRole('ADMIN')") public Category cat(@RequestBody Category x){return categories.save(x);} @PutMapping("/categories/{id}") @PreAuthorize("hasRole('ADMIN')") public Category cat(@PathVariable Long id,@RequestBody Category x){x.id=id;return categories.save(x);} @DeleteMapping("/categories/{id}") @PreAuthorize("hasRole('ADMIN')") public void cat(@PathVariable Long id){categories.deleteById(id);}
 @GetMapping("/venues") public List<Venue> ven(){return venues.findAll();} @PostMapping("/venues") @PreAuthorize("hasRole('ADMIN')") public Venue ven(@RequestBody Venue x){return venues.save(x);} @PutMapping("/venues/{id}") @PreAuthorize("hasRole('ADMIN')") public Venue ven(@PathVariable Long id,@RequestBody Venue x){x.id=id;return venues.save(x);} @DeleteMapping("/venues/{id}") @PreAuthorize("hasRole('ADMIN')") public void ven(@PathVariable Long id){venues.deleteById(id);}
 @GetMapping("/announcements") public List<Announcement> ann(){return announcements.findAll();} @PostMapping("/announcements") @PreAuthorize("hasRole('ADMIN')") public Announcement ann(@RequestBody Announcement x){return announcements.save(x);} @PutMapping("/announcements/{id}") @PreAuthorize("hasRole('ADMIN')") public Announcement ann(@PathVariable Long id,@RequestBody Announcement x){x.id=id;return announcements.save(x);} @DeleteMapping("/announcements/{id}") @PreAuthorize("hasRole('ADMIN')") public void ann(@PathVariable Long id){announcements.deleteById(id);}
 @GetMapping("/sponsors") public List<Sponsor> sponsors(){return sponsors.findAll();} @PostMapping("/sponsors") @PreAuthorize("hasRole('ADMIN')") public Sponsor sponsor(@RequestBody Sponsor x){return sponsors.save(x);} @PutMapping("/sponsors/{id}") @PreAuthorize("hasRole('ADMIN')") public Sponsor sponsor(@PathVariable Long id,@RequestBody Sponsor x){x.id=id;return sponsors.save(x);} @DeleteMapping("/sponsors/{id}") @PreAuthorize("hasRole('ADMIN')") public void sponsor(@PathVariable Long id){sponsors.deleteById(id);}
 @GetMapping("/users") @PreAuthorize("hasRole('ADMIN')") public List<User> users(){return users.findAll();}
 @GetMapping("/results") public List<Result> results(){return results.findAll();} @PostMapping("/results") @PreAuthorize("hasAnyRole('ADMIN','COORDINATOR','JUDGE')") public Result result(@RequestBody Result x){return results.save(x);} @PutMapping("/results/{id}") @PreAuthorize("hasAnyRole('ADMIN','COORDINATOR','JUDGE')") public Result result(@PathVariable Long id,@RequestBody Result x){x.id=id;return results.save(x);}
 @GetMapping("/schedules") public List<Schedule> schedules(){return schedules.findAll();} @PostMapping("/schedules") @PreAuthorize("hasAnyRole('ADMIN','COORDINATOR')") public Schedule schedule(@RequestBody Schedule x){return schedules.save(x);}
 @PostMapping("/feedback") @PreAuthorize("hasRole('STUDENT')") public Feedback feedback(@RequestBody Feedback x){return feedback.save(x);} @GetMapping("/feedback") @PreAuthorize("hasRole('ADMIN')") public List<Feedback> feedback(){return feedback.findAll();}
 @GetMapping("/notifications") public List<Notification> notifications(){return notifications.findAll();}
}
